import jwt from "jsonwebtoken";
var createToken = (payload) => {
  return jwt.sign(
    payload,
    process.env.JWT_SECRET,
    {
      expiresIn: "7d"
    }
  );
};

// src/modules/auth/auth.service.ts
var registerUser = async (data) => {
  const existingUser = await prisma_default.user.findUnique({
    where: {
      email: data.email
    }
  });
  if (existingUser) {
    throw new app_error_default(
      409,
      "User already exists with this email"
    );
  }
  const hashedPassword = await bcrypt.hash(
    data.password,
    12
  );
  const user = await prisma_default.user.create({
    data: {
      name: data.name,
      email: data.email,
      password: hashedPassword,
      role: data.role || "CUSTOMER"
    },
    select: {
      id: true,
      name: true,
      email: true,
      role: true,
      status: true
    }
  });
  const token = createToken({
    id: user.id,
    email: user.email,
    role: user.role
  });
  return {
    user,
    token
  };
};
var loginUser = async (data) => {
  const user = await prisma_default.user.findUnique({
    where: {
      email: data.email
    }
  });
  if (!user) {
    throw new app_error_default(
      401,
      "Invalid email or password"
    );
  }
  const passwordMatched = await bcrypt.compare(
    data.password,
    user.password
  );
  if (!passwordMatched) {
    throw new app_error_default(
      401,
      "Invalid email or password"
    );
  }
  const token = createToken({
    id: user.id,
    email: user.email,
    role: user.role
  });
  return {
    user: {
      id: user.id,
      name: user.name,
      email: user.email,
      role: user.role,
      status: user.status
    },
    token
  };
};

