import { z } from "zod";
var registerValidation = z.object({
  name: z.string().min(2, "Name must be at least 2 characters"),
  email: z.string().email("Invalid email address"),
  password: z.string().min(6, "Password must be at least 6 characters"),
  role: z.enum([
    "CUSTOMER",
    "TECHNICIAN",
    "ADMIN"
  ]).optional()
});
var loginValidation = z.object({
  email: z.string().email("Invalid email address"),
  password: z.string().min(1, "Password is required")
});

// src/utils/send-response.ts
var sendResponse = (res, statusCode, responseData) => {
  res.status(statusCode).json(responseData);
};

// src/modules/auth/auth.controller.ts
var register = async (req, res, next) => {
  try {
    const validatedData = registerValidation.parse(req.body);
    const result = await registerUser(validatedData);
    sendResponse(res, 201, {
      success: true,
      message: "User registered successfully",
      data: result
    });
  } catch (error) {
    next(error);
  }
};
var login = async (req, res, next) => {
  try {
    const validatedData = loginValidation.parse(req.body);
    const result = await loginUser(validatedData);
    sendResponse(res, 200, {
      success: true,
      message: "Login successful",
      data: result
    });
  } catch (error) {
    next(error);
  }
};

